import {SCENARIOS,PLAYERS,events,position,distance} from './engine.js';
export function playEvidence(input={}){
 const s=SCENARIOS.find(s=>s.id===input.scenario)||SCENARIOS[0],time=Math.max(0,Math.min(s.duration,Number(input.time)||0));
 const l=input.language||'en',t=(en,es,pt)=>({en,es,pt}[l]||en);
 const corrected=!!input.corrected&&s.id==='wide',tracking=input.tracking!==false;
 const seen=events(s).filter(e=>e.end<=time),passes=seen.filter(e=>e.type==='pass'),last=passes.find(e=>e.id===input.eventId)||passes.at(-1);
 const off=PLAYERS.filter(p=>s.tracks[p.id]&&!seen.some(e=>[e.from,e.to,e.interceptor].includes(p.id))).map(p=>({...p,metres:distance(position(s,p.id,0,corrected),position(s,p.id,time,corrected))})).sort((a,b)=>b.metres-a.metres)[0];
 const shifted=Math.abs(position(s,102,time,corrected)[1]-position(s,102,0,corrected)[1]);
 const movement=!tracking?'Tracking unavailable: no movement claim can be supported.':s.id==='wide'?corrected&&time>0?'Laurent stays at his starting position. The earlier movement claim is withdrawn.':`Laurent shifts ${shifted.toFixed(1)} m laterally from his starting position.`:off?`${off.name} is ${off.metres.toFixed(1)} m from their starting position.`:'No off-ball movement identified yet.';
 const facts={passes:passes.length,complete:passes.filter(e=>e.outcome==='complete').length,goals:seen.filter(e=>e.outcome==='goal').length,ids:seen.map(e=>e.id)};
 const localizedMovement=!tracking?t('Tracking unavailable: no movement claim can be supported.','Seguimiento no disponible: no se puede sostener una afirmación de movimiento.','Rastreamento indisponível: não se pode sustentar uma afirmação de movimento.'):s.id==='wide'?corrected&&time>0?t('Laurent stays at his starting position. The earlier movement claim is withdrawn.','Laurent permanece en su posición inicial. Se retira la afirmación anterior de movimiento.','Laurent permanece na posição inicial. A afirmação anterior de movimento é retirada.'):t(`Laurent shifts ${shifted.toFixed(1)} m laterally from his starting position.`,`Laurent se desplaza ${shifted.toFixed(1)} m lateralmente desde su posición inicial.`,`Laurent se desloca ${shifted.toFixed(1)} m lateralmente desde a posição inicial.`):off?t(`${off.name} is ${off.metres.toFixed(1)} m from their starting position.`,`${off.name} está a ${off.metres.toFixed(1)} m de su posición inicial.`,`${off.name} está a ${off.metres.toFixed(1)} m da posição inicial.`):t('No off-ball movement identified yet.','Aún no se identifica movimiento sin balón.','Ainda não há movimento sem bola identificado.');
 const harbor=passes.filter(e=>e.team==='harbor'),lost=seen.filter(e=>e.team==='north'&&e.outcome==='intercepted').length;
 const names=id=>PLAYERS.find(p=>p.id===id)?.name||'Unknown player';
 return {s,time,corrected,tracking,seen,last,off:tracking?off:null,facts,movement:localizedMovement,
 pass:last?`${names(last.from)} → ${names(last.interceptor||last.to)}: ${last.distance.toFixed(1)} m ${t('in','en','em')} ${(last.end-last.t).toFixed(1)} s (${last.speed.toFixed(1)} km/h). ${t(last.outcome,last.outcome==='complete'?'completo':'interceptado',last.outcome==='complete'?'completo':'interceptado')}.`:t('No completed pass is available at this point.','No hay un pase completado en este instante.','Não há passe completo neste instante.'),
 source:`${s.id} · ${time.toFixed(1)} s · ${corrected?'corrected':'original'} tracking`,
 trail:id=>tracking?Array.from({length:Math.floor(time)+1},(_,t)=>position(s,id,t,corrected)).concat([position(s,id,time,corrected)]):[],
 perspectives:[
 {club:'Harbor FC',angle:t(`Our attacking route: ${harbor.filter(e=>e.outcome==='complete').length}/${harbor.length} passes reached a teammate.`,`Nuestra ruta de ataque: ${harbor.filter(e=>e.outcome==='complete').length}/${harbor.length} pases llegaron a un compañero.`,`Nossa rota de ataque: ${harbor.filter(e=>e.outcome==='complete').length}/${harbor.length} passes chegaram a um companheiro.`)+' '+(tracking&&off&&off.team==='harbor'?t(`Follow ${off.name}'s ${off.metres.toFixed(1)} m off-ball displacement as another movement to inspect—not proof that the run created the chance.`,`Sigue los ${off.metres.toFixed(1)} m de desplazamiento sin balón de ${off.name}; no demuestra que la carrera creara la ocasión.`,`Acompanhe os ${off.metres.toFixed(1)} m de deslocamento sem bola de ${off.name}; isso não prova que a corrida criou a chance.`):t('Judge the passing first; do not invent an unmeasured attacking contribution.','Evalúa primero los pases; no inventes una contribución ofensiva no medida.','Avalie primeiro os passes; não invente uma contribuição ofensiva não medida.')),facts},
 {club:'Northbridge',angle:s.id==='wide'?localizedMovement+' '+t('Our defensive question: did the marking position change? Tracking can answer that; it cannot establish why.','Nuestra pregunta defensiva: ¿cambió la posición de marcaje? El seguimiento puede responder eso, pero no el motivo.','Nossa pergunta defensiva: a posição de marcação mudou? O rastreamento responde isso, mas não o motivo.'):s.id==='press'?t(`Our possession risk: ${lost} intercepted pass recorded against Northbridge. Review the outlet under pressure; the event does not assign individual blame.`,`Nuestro riesgo de posesión: ${lost} pase interceptado registrado contra Northbridge. Revisa la salida bajo presión; el evento no atribuye culpa individual.`,`Nosso risco de posse: ${lost} passe interceptado registrado contra Northbridge. Reveja a saída sob pressão; o evento não atribui culpa individual.`):seen.some(e=>e.type==='shot')?t('Berg recorded a save. Evaluate the goalkeeper’s outcome separately from whether the preceding transition was well defended.','Berg registró una parada. Evalúa el resultado del portero por separado de la defensa de la transición.','Berg registrou uma defesa. Avalie o resultado do goleiro separadamente da defesa da transição.'):t('Our recovery question: can the defence reorganize before a shot? The shot outcome is not available yet.','Nuestra pregunta de recuperación: ¿puede reorganizarse la defensa antes del tiro? El resultado aún no está disponible.','Nossa pergunta de recuperação: a defesa consegue se reorganizar antes do chute? O resultado ainda não está disponível.'),facts}
 ]};
}
